import{_ as p,a0 as i,w as l,s as o,ao as s,I as a,x as e,a1 as u,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"如何在 Ubuntu 中加密硬盤 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中加密硬盤 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中加密硬盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中加密硬盤 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170113 How to Encrypt Your Hard Disk in Ubuntu","title":"如何在 Ubuntu 中加密硬盤","tag":"201702","desc":""},"relativePath":"201702/20170113 How to Encrypt Your Hard Disk in Ubuntu.md","filePath":"[post].md"}'),d={name:"201702/20170113 How to Encrypt Your Hard Disk in Ubuntu.md"};function m(b,t,f,k,h,y){const n=i("Link");return l(),o("div",null,[t[26]||(t[26]=s('<h1 id="如何在-ubuntu-中加密硬盤" tabindex="-1">如何在 Ubuntu 中加密硬盤 <a class="header-anchor" href="#如何在-ubuntu-中加密硬盤" aria-label="Permalink to “如何在 Ubuntu 中加密硬盤”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/hdd-encryption-ubuntu.jpg" alt="" title="How to Encrypt Your Hard Disk in Ubuntus"></p><p>隱私保護、安全和加密是不可分開的，用户可以通過加密來提高安全和保護操作系統的隱私信息。本文將會介紹在 Ubuntu Linux 中對硬盤全盤加密的優缺點。此外，我們也介紹如何在系統級別上進行加密設置，並對一些目錄進行加密。加密是非常有用的，而且也沒有你想像中那麼複雜。綜上所述，讓我開始進行加密吧。</p><h3 id="加密的優缺點" tabindex="-1">加密的優缺點 <a class="header-anchor" href="#加密的優缺點" aria-label="Permalink to “加密的優缺點”">​</a></h3><p>儘管進行全盤加密聽起來非常棒，但是否要這麼做還是有些爭議的。我們先來看看這個做法有哪些優缺點。</p><h4 id="加密的優點" tabindex="-1">加密的優點 <a class="header-anchor" href="#加密的優點" aria-label="Permalink to “加密的優點”">​</a></h4><ul><li>提高私密程度</li><li>只有擁有密鑰的人才能訪問操作系統及其中文件</li><li>確保政府或者黑客無法偵測你的系統和侵犯你的隱私</li></ul><h4 id="加密的缺點" tabindex="-1">加密的缺點 <a class="header-anchor" href="#加密的缺點" aria-label="Permalink to “加密的缺點”">​</a></h4><ul><li>在其他的 Linux 操作系統上訪問和掛載文件系統將變得困難</li><li>無法從那些加密分區中恢復數據</li><li>如果用户丟失了加密密鑰，那就徹底悲劇了</li></ul><h3 id="安裝前的準備" tabindex="-1">安裝前的準備 <a class="header-anchor" href="#安裝前的準備" aria-label="Permalink to “安裝前的準備”">​</a></h3>',10)),a("p",null,[t[2]||(t[2]=e("在 Ubuntu 中加密最好就是在安裝進程開始之前在系統層面進行。在 Ubuntu 安裝進程開始之後是無法加密的，所以先備份你的重要數據到 ",-1)),u(n,{href:"http://www.maketecheasier.com/tag/dropbox"},{default:r(()=>[...t[0]||(t[0]=[e("Dropbox",-1)])]),_:1}),t[3]||(t[3]=e("、 ",-1)),u(n,{href:"http://www.maketecheasier.com/tag/google-drive"},{default:r(()=>[...t[1]||(t[1]=[e("Google Drive",-1)])]),_:1}),t[4]||(t[4]=e(" （或者其它硬盤上），然後後準備重新安裝 Ubuntu。",-1))]),t[27]||(t[27]=a("p",null,[a("img",{src:"https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-ubuntu-alternative-downloads.jpg",alt:"ubuntu 下載",title:"ubuntu-encrypt-ubuntu-alternative-downloads"})],-1)),a("p",null,[t[6]||(t[6]=e("從 ",-1)),u(n,{href:"https://www.ubuntu.com/download/alternative-downloads"},{default:r(()=>[...t[5]||(t[5]=[e("此處",-1)])]),_:1}),t[7]||(t[7]=e(" 開始下載最新版本的 Ubuntu，並製作好可啓動的 U 盤 （需要至少 2 GB 可用空間）。",-1))]),a("p",null,[t[9]||(t[9]=e("製作啓動 U 盤需要一個燒錄程序，可以到 ",-1)),u(n,{href:"https://etcher.io/"},{default:r(()=>[...t[8]||(t[8]=[e("etcher.io",-1)])]),_:1}),t[10]||(t[10]=e(" 去下載。下載好之後解壓 zip 文件，右擊 (或者使用鼠標選定之後按下回車) 解壓出來的文件以運行。",-1))]),t[28]||(t[28]=s('<p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-etcher.jpg" alt="燒錄程序" title="ubuntu-encrypt-etcher"></p><p><strong>注意</strong>：燒錄程序會詢問是否創建圖標，選擇“yes”。</p><p>在燒錄程序中點擊“選擇鏡像（Select Image）”按鈕，選擇之前下載好的 Ubuntu ISO 鏡像。然後插入你的 U 盤。燒錄程序會自動檢測併為你選擇。最後，點擊“開始燒錄（ Flash）”按鈕來開始創建進程。</p><p>完成之後，重啓電腦至 BIOS，設置為 U 盤啓動。</p><p><strong>注意</strong>：如果你的電腦不支持從 U 盤啓動，下載 32 位的 Ubuntu，並使用你電腦中的燒錄軟件將其燒錄到 DVD 中。</p><h3 id="對你的硬盤進行全盤加密" tabindex="-1">對你的硬盤進行全盤加密 <a class="header-anchor" href="#對你的硬盤進行全盤加密" aria-label="Permalink to “對你的硬盤進行全盤加密”">​</a></h3><p>加載好 Live Ubuntu 之後，安裝進程就可以開始了。當 Ubuntu 安裝進程開始之後，會出現下面這樣一個界面。注意每個人安裝進程都可能不同的，或許你會看到的不太一樣。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-installation-type1.jpg" alt="" title="ubuntu-encrypt-installation-type"></p><p>選擇“擦除磁盤並安裝 Ubuntu （Erase disk and install Ubuntu）”,並選擇“加密新裝的 Ubuntu 以提高安全程度（Encrypt the new Ubuntu installation for Security）”來開始加密的安裝進程。這樣會自動選擇 LVM。兩個選框都必須選中。選好加密選項之後，點擊“現在安裝（Install Now）”。</p><p><strong>注意</strong>：如果是雙系統啓動的話，你需要安裝到空餘磁盤空間，而非擦除磁盤。選擇好之後，像上邊一樣選擇加密選項。</p><p>選擇加密選項並開始安裝之後，會出現一個加密配置頁面。這個頁面用户需要為安裝進程設置自己的加密密鑰。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-choose-security-key.jpg" alt="設置安全密碼" title="ubuntu-encrypt-choose-security-key"></p><p>輸入安全密鑰。該安全密鑰設置窗口會自動為你輸入的密鑰進行密碼強度評級，使用這個功能時看着後邊的顯示，直到顯示為“高強度密碼（strong password）”為止。輸入完成後，在下方在此輸入來確認密碼，最後用一張紙把密碼寫下下來妥善保管。</p><p>此外，選定“覆些磁盤空餘空間（Overwrite empty disk space）”，當然這是一個可選步驟。一切準備就緒之後點擊現在安裝即可。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-timezone-select.jpg" alt="選擇時區" title="ubuntu-encrypt-timezone-select"></p><p>在設置完加密密鑰之後，就是傳統的 Ubuntu 安裝配置了。選擇時區、創建用户以及對應的安全密碼。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-home-folder-e1483900399596.jpg" alt="加密家目錄" title="ubuntu-encrypt-home-folder"></p><p>與創建和加密 Ubuntu 磁盤對應，在創建用户的時記得候選擇“登錄系統需要密碼（require my password to log in）”和“加密我的家目錄（encrypt my home folder）”。這樣可以為你的數據再增加一層保護。</p><p>等到用户名、加密設置以及其他所有事情都完成之後，Ubuntu 安裝進程就可以開始了。隨後，安裝進程會告知你安裝已完成，移除安裝介質後重啓即可享受 Ubuntu 之旅。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>進行磁盤加密之後，如果沒有加密密鑰則無法開啓 Ubuntu。儘管無趣，但這種級別的加密使用最容易的，並且還充分利用了操作系統提供的特性。用户不需要過多的知識，或者使用其他第三方程序就可以很快完成加密要求。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-decrypt-computer.jpg" alt="加密電腦" title="ubuntu-encrypt-decrypt-computer"></p><p>加密之後的 Ubuntu，使用起來和沒有加密的並沒有什麼區別。不需要其他的步驟，也不需要學習什麼複雜的解密方法。對於那些非常在意隱私但又不想太過麻煩的人來説，這個提高安全等級的方法是必須學會的（當然，這很容易不是嗎）。</p><p>你是否會使用 Ubuntu 對硬盤進行加密呢？在下方評論告訴我們。</p><hr><p>譯者簡介：</p>',26)),a("p",null,[u(n,{href:"http://GHLandy.com"},{default:r(()=>[...t[11]||(t[11]=[e("GHLandy",-1)])]),_:1}),t[12]||(t[12]=e(" —— 欲得之，則為之奮鬥 (If you want it, work for it.)。",-1))]),t[29]||(t[29]=a("hr",null,null,-1)),a("p",null,[t[14]||(t[14]=e("via: ",-1)),u(n,{href:"https://www.maketecheasier.com/encrypt-hard-disk-in-ubuntu/"},{default:r(()=>[...t[13]||(t[13]=[e("https://www.maketecheasier.com/encrypt-hard-disk-in-ubuntu/",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=e("作者：",-1)),u(n,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:r(()=>[...t[15]||(t[15]=[e("Derrik Diener",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),u(n,{href:"https://github.com/GHLandy"},{default:r(()=>[...t[16]||(t[16]=[e("GHLandy",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),u(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[23]||(t[23]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),u(n,{href:"https://linux.cn/"},{default:r(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const x=p(d,[["render",m]]);export{U as __pageData,x as default};
